// Map last_visit_range enum keys to ISO date ranges server-side (C1 fix)
function resolveLastVisitRange(range: string): { from: string | null; to: string | null } {
  const now = new Date()
  const toISO = (d: Date) => d.toISOString().slice(0, 10)
  switch (range) {
    case '7d': {
      const from = new Date(now)
      from.setDate(from.getDate() - 7)
      return { from: toISO(from), to: toISO(now) }
    }
    case '30d': {
      const from = new Date(now)
      from.setDate(from.getDate() - 30)
      return { from: toISO(from), to: toISO(now) }
    }
    case '90d': {
      const from = new Date(now)
      from.setDate(from.getDate() - 90)
      return { from: toISO(from), to: toISO(now) }
    }
    case 'all':
      return { from: null, to: null }
    default:
      return { from: null, to: null }
  }
}

