'use client'
import { useEffect, useState } from 'react'

/**
 * Returns true when window.innerWidth < breakpoint.
 * Starts false (SSR-safe) and hydrates on mount.
 */
export function useIsMobile(breakpoint = 768): boolean {
  const [isMobile, setIsMobile] = useState(false)

  useEffect(() => {
    function check() {
      setIsMobile(window.innerWidth < breakpoint)
    }
    check()
    window.addEventListener('resize', check, { passive: true })
    return () => window.removeEventListener('resize', check)
  }, [breakpoint])

  return isMobile
}

'use client'
import { useEffect } from 'react'

/**
 * Scrolls the currently focused input into view when the virtual keyboard
 * opens. Uses the visualViewport API (supported in all modern mobile browsers).
 * Graceful no-op when visualViewport is not available.
 */
export function useKeyboardAware() {
  useEffect(() => {
    const vv = window.visualViewport
    if (!vv) return

    function handleResize() {
      const active = document.activeElement as HTMLElement | null
      if (!active) return
      const tag = active.tagName.toLowerCase()
      if (tag !== 'input' && tag !== 'textarea' && !active.isContentEditable) return
      // Keyboard is open — scroll active input into center of visible area
      active.scrollIntoView({ behavior: 'smooth', block: 'center' })
    }

    vv.addEventListener('resize', handleResize)
    return () => vv.removeEventListener('resize', handleResize)
  }, [])
}
